CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, username text UNIQUE CHECK (username IS NULL OR username ~ '^[a-z0-9_]{3,30}$'), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own ON public.profiles FOR ALL TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_caregiver_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES (NEW.id) ON CONFLICT DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER create_caregiver_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_caregiver_profile();
CREATE TABLE public.children (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, nickname text NOT NULL CHECK (char_length(nickname) BETWEEN 1 AND 60), age_group text NOT NULL CHECK(age_group IN ('toddler','preschool')), preferences text NOT NULL DEFAULT '' CHECK(char_length(preferences) <= 1000), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.children TO authenticated;
GRANT ALL ON public.children TO service_role;
ALTER TABLE public.children ENABLE ROW LEVEL SECURITY;
CREATE POLICY children_own ON public.children FOR ALL TO authenticated USING(user_id = auth.uid()) WITH CHECK(user_id = auth.uid());
CREATE INDEX children_owner ON public.children(user_id);
CREATE TABLE public.activity_completions (id uuid PRIMARY KEY, user_id uuid NOT NULL, child_id uuid, activity jsonb NOT NULL CHECK(jsonb_typeof(activity) = 'object'), age text NOT NULL CHECK(age IN ('toddler','preschool')), energy text NOT NULL CHECK(energy IN ('zoomies','overstimulated','winddown','fatigue')), env text NOT NULL CHECK(env IN ('kaamos','kurakeli','pakkanen','livingroom')), completed_at timestamptz NOT NULL, stars integer NOT NULL CHECK(stars BETWEEN 1 AND 5), notes text NOT NULL DEFAULT '' CHECK(char_length(notes) <= 5000), video_path text CHECK(video_path IS NULL OR split_part(video_path,'/',1) = user_id::text), FOREIGN KEY(child_id,user_id) REFERENCES public.children(id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.activity_completions TO authenticated;
GRANT ALL ON public.activity_completions TO service_role;
ALTER TABLE public.activity_completions ENABLE ROW LEVEL SECURITY;
CREATE POLICY completions_own ON public.activity_completions FOR ALL TO authenticated USING(user_id = auth.uid()) WITH CHECK(user_id = auth.uid());
CREATE INDEX completions_owner ON public.activity_completions(user_id,completed_at DESC);
CREATE POLICY activity_video_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id = 'activity-clips' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY activity_video_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id = 'activity-clips' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY activity_video_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id = 'activity-clips' AND (storage.foldername(name))[1] = auth.uid()::text);